// Temporary golden-output test: writes every list answer to $GOLDEN_OUT. Not to be committed.
func TestZZGolden(t *testing.T) {
	out := os.Getenv("GOLDEN_OUT")
	if out == "" {
		t.Skip()
	}
	e := apitest.New(t)
	base := apitest.Start
	var buf []byte
	emit := func(path string, r *apitest.Response) {
		buf = append(buf, fmt.Sprintf("%s -> %d\n%s\n", path, r.Code, r.Body)...)
	}
	var acmeCus, globexCus []store.Customer
	for i := 0; i < 6; i++ {
		c, err := e.Store.CreateCustomer(e.Acme.ID, fmt.Sprintf("Acme %d", i), fmt.Sprintf("c%d@acme.example", i), base.Add(time.Duration(i)*time.Minute))
		if err != nil {
			t.Fatal(err)
		}
		acmeCus = append(acmeCus, c)
	}
	for i := 0; i < 2; i++ {
		c, err := e.Store.CreateCustomer(e.Globex.ID, fmt.Sprintf("Globex %d", i), fmt.Sprintf("c%d@globex.example", i), base)
		if err != nil {
			t.Fatal(err)
		}
		globexCus = append(globexCus, c)
	}
	var ids []string
	mk := func(org store.Org, c store.Customer, sub string, at time.Time, lines int, disc int) store.Invoice {
		var ls []store.Line
		for l := 0; l < lines; l++ {
			ls = append(ls, store.Line{Description: fmt.Sprintf("line %d", l), Quantity: int64(l + 1), UnitAmount: int64(1000 + 7*l)})
		}
		inv, err := e.Store.CreateInvoice(store.Invoice{OrgID: org.ID, CustomerID: c.ID, SubscriptionID: sub, Currency: money.USD, Lines: ls, DiscountPercent: disc}, at)
		if err != nil {
			t.Fatal(err)
		}
		ids = append(ids, inv.ID)
		return inv
	}
	// Creation order differs from time order; ties on time; some subscriptions; some orgs interleaved.
	for i := 0; i < 60; i++ {
		at := base.Add(time.Duration((i*37)%23) * time.Minute)
		c := acmeCus[(i*5)%len(acmeCus)]
		sub := ""
		if i%3 == 0 {
			sub = fmt.Sprintf("sub_%d", i%4)
		}
		inv := mk(e.Acme.Org, c, sub, at, 1+i%3, (i%4)*5)
		if i%11 == 0 {
			e.Store.UpdateInvoice(e.Acme.ID, inv.ID, func(x *store.Invoice) error { x.Status = store.InvoicePaid; x.PaidAt = &at; return nil })
		}
		if i%13 == 0 {
			e.Store.UpdateInvoice(e.Acme.ID, inv.ID, func(x *store.Invoice) error { x.Status = store.InvoiceVoid; x.VoidedAt = &at; return nil })
		}
		if i%5 == 0 {
			mk(e.Globex.Org, globexCus[i%2], "", at, 1, 0)
		}
	}
	// A deleted customer's invoices, and a renamed customer.
	e.Store.DeleteCustomer(e.Acme.ID, acmeCus[1].ID)
	e.Store.UpdateCustomer(e.Acme.ID, acmeCus[2].ID, func(c *store.Customer) error { c.Name = "Renamed"; return nil })

	filters := []string{"", "?customer_id=" + acmeCus[0].ID, "?customer_id=" + acmeCus[1].ID, "?customer_id=" + globexCus[0].ID,
		"?customer_id=nope", "?subscription_id=sub_1", "?subscription_id=sub_2", "?subscription_id=none", "?status=open", "?status=paid",
		"?status=void", "?status=open&customer_id=" + acmeCus[2].ID, "?status=paid&subscription_id=sub_0", "?status=lost", "?limit=0",
		"?limit=101", "?limit=x", "?cursor=bad", "?cursor=", "?status=", "?limit=5&status=void"}
	for _, f := range filters {
		for _, lim := range []string{"", "&limit=1", "&limit=3", "&limit=7", "&limit=100"} {
			path := "/v1/invoices" + f
			sep := "?"
			if f != "" {
				sep = "&"
			}
			if f == "" && lim != "" {
				sep = "?"
			}
			full := path
			if lim != "" {
				full = path + sep + lim[1:]
			}
			cur := ""
			for pages := 0; pages < 500; pages++ {
				p := full
				if cur != "" {
					if containsQuery(p) {
						p += "&cursor=" + cur
					} else {
						p += "?cursor=" + cur
					}
				}
				r := e.Do("GET", p, e.Acme.Key, nil)
				emit(p, r)
				m := r.Map(t)
				next, _ := m["next_cursor"].(string)
				if next == "" {
					break
				}
				cur = next
			}
		}
	}
	// Crafted cursors: between items, past the end, and naming a nonexistent ID.
	for _, c := range []cursor{
		{T: base.Add(5 * time.Minute), ID: "in_000003"},
		{T: base.Add(500 * time.Hour), ID: "zz"},
		{T: base.Add(-time.Hour), ID: "a"},
		{T: base.Add(3 * time.Minute), ID: "in_000004"},
	} {
		for _, f := range []string{"", "?status=open", "?customer_id=" + acmeCus[3].ID} {
			p := "/v1/invoices" + f
			if containsQuery(p) {
				p += "&limit=4&cursor=" + encodeCursor(c)
			} else {
				p += "?limit=4&cursor=" + encodeCursor(c)
			}
			emit(p, e.Do("GET", p, e.Acme.Key, nil))
		}
	}
	// Another organization's key sees only its own invoices; no key is refused.
	emit("globex", e.Do("GET", "/v1/invoices", e.Globex.Key, nil))
	emit("nokey", e.Do("GET", "/v1/invoices", "", nil))
	_ = http.StatusOK
