	out := []Invoice{}
	for _, id := range ids[start:] {
		inv := s.invoices[id]
		if (f.CustomerID != "" && inv.CustomerID != f.CustomerID) || (f.SubscriptionID != "" && inv.SubscriptionID != f.SubscriptionID) || (f.Status != "" && inv.Status != f.Status) {
			continue
		}
		if len(out) == limit {
			return out, true
		}
		out = append(out, copyInvoice(inv))
	}
	return out, false
}

