package store

import (
	"fmt"
	"reflect"
	"sort"
	"testing"
	"time"

	"example.com/tally/internal/money"
)

// wantInvoiceIDs is the answer a list should give, computed without the store's own list code: the invoices of the
// organization that match f, sorted by creation time then ID.
func wantInvoiceIDs(s *Store, orgID string, f InvoiceFilter) []string {
	var matching []Invoice
	for _, inv := range s.Export().Invoices {
		if inv.OrgID != orgID || (f.CustomerID != "" && inv.CustomerID != f.CustomerID) ||
			(f.SubscriptionID != "" && inv.SubscriptionID != f.SubscriptionID) || (f.Status != "" && inv.Status != f.Status) {
			continue
		}
		matching = append(matching, inv)
	}
	sort.Slice(matching, func(i, j int) bool {
		if !matching[i].CreatedAt.Equal(matching[j].CreatedAt) {
			return matching[i].CreatedAt.Before(matching[j].CreatedAt)
		}
		return matching[i].ID < matching[j].ID
	})
	ids := []string{}
	for _, inv := range matching {
		ids = append(ids, inv.ID)
	}
	return ids
}

// walkInvoicePages follows ListInvoicesAfter from the start, pages of limit, and returns the IDs it sees.
func walkInvoicePages(t *testing.T, s *Store, orgID string, f InvoiceFilter, limit int) []string {
	t.Helper()
	ids := []string{}
	var afterT time.Time
	afterID := ""
	for pages := 0; ; pages++ {
		if pages > 10000 {
			t.Fatal("paging does not end")
		}
		page, more := s.ListInvoicesAfter(orgID, f, afterT, afterID, limit)
		if len(page) > limit || (more && len(page) == 0) {
			t.Fatalf("page of %d for limit %d (more %v)", len(page), limit, more)
		}
		for _, inv := range page {
			ids = append(ids, inv.ID)
		}
		if !more {
			return ids
		}
		last := page[len(page)-1]
		afterT, afterID = last.CreatedAt, last.ID
	}
}

func TestListInvoicesPagesMatchWholeList(t *testing.T) {
	s := New()
	a := newOrg(t, s, "A")
	b := newOrg(t, s, "B")
	ca, _ := s.CreateCustomer(a.ID, "Ann", "ann@example.com", t0)
	cb, _ := s.CreateCustomer(b.ID, "Ben", "ben@example.com", t0)
	// Creation order is not time order, several invoices share a time, and the organizations' invoices interleave.
	minutes := []int{5, 1, 3, 3, 0, 5, 2, 3, 1, 4, 0, 4}
	for i, m := range minutes {
		org, c := a, ca
		if i%3 == 2 {
			org, c = b, cb
		}
		inv := Invoice{OrgID: org.ID, CustomerID: c.ID, Currency: money.EUR, Lines: []Line{{Description: "x", Quantity: 1, UnitAmount: 100}}}
		if i%4 != 3 {
			inv.SubscriptionID = fmt.Sprintf("sub_%d", i%2)
		}
		created, err := s.CreateInvoice(inv, t0.Add(time.Duration(m)*time.Minute))
		if err != nil {
			t.Fatal(err)
		}
		if i == 4 {
			if _, err := s.UpdateInvoice(org.ID, created.ID, func(x *Invoice) error { x.Status = InvoicePaid; return nil }); err != nil {
				t.Fatal(err)
			}
		}
		if i == 7 {
			if _, err := s.UpdateInvoice(org.ID, created.ID, func(x *Invoice) error { x.Status = InvoiceVoid; return nil }); err != nil {
				t.Fatal(err)
			}
		}
	}
	filters := []InvoiceFilter{
		{}, {CustomerID: ca.ID}, {CustomerID: cb.ID}, {CustomerID: "cus_nope"}, {SubscriptionID: "sub_0"}, {SubscriptionID: "sub_1"},
		{Status: InvoiceOpen}, {Status: InvoicePaid}, {Status: InvoiceVoid}, {CustomerID: ca.ID, Status: InvoiceOpen},
		{SubscriptionID: "sub_1", Status: InvoicePaid},
	}
	for _, org := range []Org{a, b} {
		for _, f := range filters {
			want := wantInvoiceIDs(s, org.ID, f)
			if got := s.ListInvoices(org.ID, f); !reflect.DeepEqual(invoiceIDs(got), want) {
				t.Fatalf("ListInvoices(%+v) = %v, want %v", f, invoiceIDs(got), want)
			}
			for limit := 1; limit <= len(want)+1; limit++ {
				if got := walkInvoicePages(t, s, org.ID, f, limit); !reflect.DeepEqual(got, want) {
					t.Fatalf("pages of %d for %+v = %v, want %v", limit, f, got, want)
				}
			}
		}
	}
}

func invoiceIDs(invs []Invoice) []string {
	ids := []string{}
	for _, inv := range invs {
		ids = append(ids, inv.ID)
	}
	return ids
}

func TestListInvoicesAfterSeesInsertsBetweenPages(t *testing.T) {
	s := New()
	a := newOrg(t, s, "A")
	c, _ := s.CreateCustomer(a.ID, "Ann", "ann@example.com", t0)
	add := func(at time.Time) Invoice {
		inv, err := s.CreateInvoice(Invoice{OrgID: a.ID, CustomerID: c.ID, Currency: money.EUR, Lines: []Line{{Description: "x", Quantity: 1, UnitAmount: 1}}}, at)
		if err != nil {
			t.Fatal(err)
		}
		return inv
	}
	for m := 0; m < 4; m++ {
		add(t0.Add(time.Duration(10+m) * time.Minute))
	}
	first, more := s.ListInvoicesAfter(a.ID, InvoiceFilter{}, time.Time{}, "", 2)
	if !more || len(first) != 2 {
		t.Fatalf("first page = %d items, more %v", len(first), more)
	}
	last := first[1]
	// One invoice lands before the cursor (a clock that moved back), one after everything.
	before := add(t0.Add(5 * time.Minute))
	after := add(t0.Add(time.Hour))
	page, more := s.ListInvoicesAfter(a.ID, InvoiceFilter{}, last.CreatedAt, last.ID, 10)
	if more {
		t.Fatalf("the rest should fit one page: %v", invoiceIDs(page))
	}
	got := invoiceIDs(page)
	want := []string{}
	for _, id := range wantInvoiceIDs(s, a.ID, InvoiceFilter{}) {
		if id != before.ID && (id > last.ID || s.mustInvoice(id).CreatedAt.After(last.CreatedAt)) {
			want = append(want, id)
		}
	}
	if !reflect.DeepEqual(got, want) || got[len(got)-1] != after.ID {
		t.Fatalf("rest after the cursor = %v, want %v and ending with %s", got, want, after.ID)
	}
	if !reflect.DeepEqual(walkInvoicePages(t, s, a.ID, InvoiceFilter{}, 1), wantInvoiceIDs(s, a.ID, InvoiceFilter{})) {
		t.Fatal("a walk after the inserts does not match the whole list")
	}
}

func TestListInvoicesFollowsStatusChanges(t *testing.T) {
	s := New()
	a := newOrg(t, s, "A")
	c, _ := s.CreateCustomer(a.ID, "Ann", "ann@example.com", t0)
	inv, err := s.CreateInvoice(Invoice{OrgID: a.ID, CustomerID: c.ID, Currency: money.EUR, Lines: []Line{{Description: "x", Quantity: 1, UnitAmount: 1}}}, t0)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := s.UpdateInvoice(a.ID, inv.ID, func(x *Invoice) error { x.Status = InvoiceVoid; return nil }); err != nil {
		t.Fatal(err)
	}
	if got := s.ListInvoices(a.ID, InvoiceFilter{Status: InvoiceOpen}); len(got) != 0 {
		t.Fatalf("open invoices after voiding = %v", invoiceIDs(got))
	}
	if got := walkInvoicePages(t, s, a.ID, InvoiceFilter{Status: InvoiceVoid}, 1); !reflect.DeepEqual(got, []string{inv.ID}) {
		t.Fatalf("void invoices = %v", got)
	}
}

func TestFromStateRebuildsInvoiceOrder(t *testing.T) {
	s := New()
	a := newOrg(t, s, "A")
	b := newOrg(t, s, "B")
	ca, _ := s.CreateCustomer(a.ID, "Ann", "ann@example.com", t0)
	cb, _ := s.CreateCustomer(b.ID, "Ben", "ben@example.com", t0)
	for i := 0; i < 20; i++ {
		org, c := a, ca
		if i%2 == 1 {
			org, c = b, cb
		}
		if _, err := s.CreateInvoice(Invoice{OrgID: org.ID, CustomerID: c.ID, Currency: money.EUR, Lines: []Line{{Description: "x", Quantity: 1, UnitAmount: 1}}}, t0.Add(time.Duration((i*7)%5)*time.Minute)); err != nil {
			t.Fatal(err)
		}
	}
	st := s.Export()
	for i, j := 0, len(st.Invoices)-1; i < j; i, j = i+1, j-1 {
		st.Invoices[i], st.Invoices[j] = st.Invoices[j], st.Invoices[i]
	}
	loaded, err := FromState(st)
	if err != nil {
		t.Fatal(err)
	}
	for _, org := range []Org{a, b} {
		want := wantInvoiceIDs(s, org.ID, InvoiceFilter{})
		if got := invoiceIDs(loaded.ListInvoices(org.ID, InvoiceFilter{})); !reflect.DeepEqual(got, want) {
			t.Fatalf("loaded list = %v, want %v", got, want)
		}
		if got := walkInvoicePages(t, loaded, org.ID, InvoiceFilter{}, 3); !reflect.DeepEqual(got, want) {
			t.Fatalf("loaded pages = %v, want %v", got, want)
		}
	}
}

// mustInvoice returns an invoice of any organization, for tests.
func (s *Store) mustInvoice(id string) Invoice {
	inv, _ := s.InvoiceByID(id)
	return inv
}

